create table public.purchase_orders (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,supplier_id bigint references public.parties(id) on delete set null,po_number text not null,status text not null default 'draft',priority text not null default 'normal',expected_delivery_date timestamptz,actual_delivery_date timestamptz,subtotal numeric(14,2) not null default 0,tax_amount numeric(14,2) not null default 0,discount_amount numeric(14,2) not null default 0,total_amount numeric(14,2) not null default 0,terms text,internal_notes text,notes text,approved_at timestamptz,sent_at timestamptz,cancelled_at timestamptz,rejected_at timestamptz,rejection_reason text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(business_id,po_number));
create table public.purchase_order_items (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,purchase_order_id bigint not null references public.purchase_orders(id) on delete cascade,product_id bigint not null references public.products(id) on delete restrict,quantity integer not null default 0 check(quantity>=0),received_quantity integer not null default 0,pending_quantity integer not null default 0,unit_price numeric(14,2) not null default 0,discount numeric(14,2) not null default 0,tax numeric(14,2) not null default 0,total numeric(14,2) not null default 0,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.goods_received_notes (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,purchase_order_id bigint references public.purchase_orders(id) on delete set null,supplier_id bigint references public.parties(id) on delete set null,grn_number text not null,received_date date not null,location text,status text not null default 'pending',notes text,verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(business_id,grn_number));
create table public.grn_items (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,grn_id bigint not null references public.goods_received_notes(id) on delete cascade,product_id bigint not null references public.products(id) on delete restrict,ordered_quantity integer not null default 0,received_quantity integer not null default 0,accepted_quantity integer not null default 0,rejected_quantity integer not null default 0,batch_number text,expiry_date date,purchase_price numeric(14,2) not null default 0,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.quality_checks (id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,grn_item_id bigint not null references public.grn_items(id) on delete cascade,check_date date not null,quality_status text not null default 'pending',defects text,damage_quantity integer not null default 0,temperature numeric,humidity numeric,photos jsonb,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
do $$ declare t text; begin for t in select unnest(array['purchase_orders','purchase_order_items','goods_received_notes','grn_items','quality_checks']) loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on table public.%I from anon,authenticated',t); execute format('grant select,insert,update,delete on table public.%I to authenticated',t); execute format('create policy %I on public.%I for all to authenticated using (business_id=(select private.current_business_id())) with check (business_id=(select private.current_business_id()))',t||'_tenant_policy',t); end loop; end $$;
create index purchase_orders_business_status_idx on public.purchase_orders(business_id,status);
create index grn_business_date_idx on public.goods_received_notes(business_id,received_date);
create index grn_items_business_grn_idx on public.grn_items(business_id,grn_id);
create index quality_checks_business_grn_idx on public.quality_checks(business_id,grn_item_id);